<?php
require_once __DIR__.'/includes/functions.php';$user=require_login();require_permission($user,'nursing.manage');$pageTitle='Catatan Keperawatan';$pdo=db();
$pdo->exec("CREATE TABLE IF NOT EXISTS nursing_followups (id INT AUTO_INCREMENT PRIMARY KEY, registration_id INT NOT NULL, nurse_employee_id INT NOT NULL, action_note TEXT NOT NULL, performed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(registration_id) REFERENCES registrations(id), FOREIGN KEY(nurse_employee_id) REFERENCES employees(id)) ENGINE=InnoDB");
$pdo->exec("CREATE TABLE IF NOT EXISTS nursing_observations (id INT AUTO_INCREMENT PRIMARY KEY, registration_id INT NOT NULL, nurse_employee_id INT NOT NULL, bp VARCHAR(30) NULL, hr VARCHAR(20) NULL, rr VARCHAR(20) NULL, temp VARCHAR(20) NULL, spo2 VARCHAR(20) NULL, notes TEXT NULL, observed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(registration_id) REFERENCES registrations(id), FOREIGN KEY(nurse_employee_id) REFERENCES employees(id)) ENGINE=InnoDB");
[$filter,$params]=patient_scope($user,'active');$sql="SELECT DISTINCT r.id,r.registration_no,p.full_name,p.medical_record_no,un.name unit_name FROM registrations r JOIN patients p ON p.id=r.patient_id JOIN units un ON un.id=r.unit_id WHERE ($filter) ORDER BY r.id DESC LIMIT 100";$q=$pdo->prepare($sql);$q->execute($params);$patients=$q->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$reg=(int)($_POST['registration_id']??0);require_patient_registration($user,$reg,'active');$action=$_POST['action']??'';try{if($action==='vitals'){$pdo->prepare('INSERT INTO nursing_observations(registration_id,nurse_employee_id,bp,hr,rr,temp,spo2,notes) VALUES(?,?,?,?,?,?,?,?)')->execute([$reg,$user['employee_id'],trim($_POST['bp']??''),trim($_POST['hr']??''),trim($_POST['rr']??''),trim($_POST['temp']??''),trim($_POST['spo2']??''),trim($_POST['notes']??'')]);flash('success','Tanda vital berhasil dicatat.');}elseif($action==='followup'){$note=trim($_POST['action_note']??'');if(!$note)throw new RuntimeException('Isi tindakan keperawatan.');$pdo->prepare('INSERT INTO nursing_followups(registration_id,nurse_employee_id,action_note) VALUES(?,?,?)')->execute([$reg,$user['employee_id'],$note]);flash('success','Tindak lanjut keperawatan tersimpan.');}else throw new RuntimeException('Aksi tidak valid.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('nursing_care.php');}
$obsQ=$pdo->prepare("SELECT no.*,p.full_name,r.registration_no,e.full_name nurse_name FROM nursing_observations no JOIN registrations r ON r.id=no.registration_id JOIN patients p ON p.id=r.patient_id JOIN employees e ON e.id=no.nurse_employee_id WHERE ($filter) ORDER BY no.id DESC LIMIT 40");$obsQ->execute($params);$obs=$obsQ->fetchAll();$actQ=$pdo->prepare("SELECT nf.*,p.full_name,r.registration_no,e.full_name nurse_name FROM nursing_followups nf JOIN registrations r ON r.id=nf.registration_id JOIN patients p ON p.id=r.patient_id JOIN employees e ON e.id=nf.nurse_employee_id WHERE ($filter) ORDER BY nf.id DESC LIMIT 40");$actQ->execute($params);$actions=$actQ->fetchAll();
require __DIR__.'/includes/header.php';?>
<h1 class="page-title">Catatan Keperawatan</h1><p class="page-subtitle">Perawat hanya dapat mencatat tanda vital, observasi, dan tindakan keperawatan yang benar-benar dilakukan. Diagnosis, asesmen medis, resep, dan instruksi dokter tidak dapat diubah di sini.</p>
<div class="grid grid-2"><div class="card"><h2 class="section-title">Input Tanda Vital</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="vitals"><div class="field"><label>Pasien / Kunjungan Aktif</label><select class="input" name="registration_id" required><option value="">-- Pilih pasien --</option><?php foreach($patients as $r):?><option value="<?=$r['id']?>"><?=e($r['registration_no'].' · '.$r['full_name'].' · '.$r['unit_name'])?></option><?php endforeach;?></select></div><div class="grid grid-2"><div class="field"><label>TD (mmHg)</label><input class="input" name="bp"></div><div class="field"><label>HR (x/menit)</label><input class="input" name="hr"></div><div class="field"><label>RR (x/menit)</label><input class="input" name="rr"></div><div class="field"><label>Suhu (°C)</label><input class="input" name="temp"></div><div class="field"><label>SpO2 (%)</label><input class="input" name="spo2"></div></div><div class="field"><label>Catatan observasi</label><textarea class="input" name="notes"></textarea></div><button class="btn btn-primary">Simpan Tanda Vital</button></form></div>
<div class="card"><h2 class="section-title">Follow-up Tindakan Keperawatan</h2><p class="note">Contoh: mengganti cairan infus sesuai instruksi, pemantauan ulang tanda vital, perawatan luka, membantu mobilisasi, atau tindakan keperawatan sesuai SOP.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="followup"><div class="field"><label>Pasien / Kunjungan Aktif</label><select class="input" name="registration_id" required><option value="">-- Pilih pasien --</option><?php foreach($patients as $r):?><option value="<?=$r['id']?>"><?=e($r['registration_no'].' · '.$r['full_name'].' · '.$r['unit_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Tindakan yang dilakukan</label><textarea class="input" name="action_note" required></textarea></div><button class="btn btn-primary">Simpan Tindak Lanjut</button></form></div></div>
<div class="card" style="margin-top:18px"><h2 class="section-title">Riwayat Tanda Vital</h2><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Pasien</th><th>TD</th><th>HR</th><th>RR</th><th>Suhu</th><th>SpO2</th><th>Perawat</th></tr></thead><tbody><?php foreach($obs as $o):?><tr><td><?=e($o['observed_at'])?></td><td><?=e($o['full_name'])?><small><?=e($o['registration_no'])?></small></td><td><?=e($o['bp'])?></td><td><?=e($o['hr'])?></td><td><?=e($o['rr'])?></td><td><?=e($o['temp'])?></td><td><?=e($o['spo2'])?></td><td><?=e($o['nurse_name'])?></td></tr><?php endforeach;?><?php if(!$obs):?><tr><td colspan="8">Belum ada catatan tanda vital.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card" style="margin-top:18px"><h2 class="section-title">Riwayat Tindak Lanjut</h2><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Pasien</th><th>Tindakan</th><th>Perawat</th></tr></thead><tbody><?php foreach($actions as $a):?><tr><td><?=e($a['performed_at'])?></td><td><?=e($a['full_name'])?><small><?=e($a['registration_no'])?></small></td><td><?=nl2br(e($a['action_note']))?></td><td><?=e($a['nurse_name'])?></td></tr><?php endforeach;?><?php if(!$actions):?><tr><td colspan="4">Belum ada tindak lanjut.</td></tr><?php endif;?></tbody></table></div></div>
